class Solution {
public:
    vector<int> processQueries(vector<int>& queries, int m) {
        vector<int> p(m);
        iota(p.begin(), p.end(), 1);
        vector<int> res;
        for (int q : queries) {
            int i = find(p.begin(), p.end(), q) - p.begin();
            res.push_back(i);
            p.erase(p.begin() + i);
            p.insert(p.begin(), q);
        }
        return res;
    }
};

