class Solution {
    public int[] processQueries(int[] queries, int m) {
        List<Integer> p = new ArrayList<>();
        for (int i = 1; i <= m; i++) p.add(i);
        int[] res = new int[queries.length];
        for (int k = 0; k < queries.length; k++) {
            int i = p.indexOf(queries[k]);
            res[k] = i;
            p.remove(i);
            p.add(0, queries[k]);
        }
        return res;
    }
}

