class Solution {
public:
    vector<int> processQueries(vector<int>& queries, int m) {
        int q = queries.size();
        int n = q + m;
        vector<int> tree(n + 1, 0), pos(m + 1);
        auto update = [&](int i, int d) {
            for (; i <= n; i += i & (-i)) tree[i] += d;
        };
        auto query = [&](int i) {
            int s = 0;
            for (; i > 0; i -= i & (-i)) s += tree[i];
            return s;
        };
        for (int v = 1; v <= m; v++) {
            pos[v] = q + v;
            update(pos[v], 1);
        }
        vector<int> res;
        int front = q;
        for (int x : queries) {
            res.push_back(query(pos[x]) - 1);
            update(pos[x], -1);
            pos[x] = front--;
            update(pos[x], 1);
        }
        return res;
    }
};

