class Solution {
    public int[] processQueries(int[] queries, int m) {
        int q = queries.length, n = q + m;
        int[] tree = new int[n + 1], pos = new int[m + 1];
        for (int v = 1; v <= m; v++) {
            pos[v] = q + v;
            add(tree, pos[v], 1);
        }
        int[] res = new int[q];
        int front = q;
        for (int k = 0; k < q; k++) {
            int x = queries[k];
            res[k] = sum(tree, pos[x]) - 1;
            add(tree, pos[x], -1);
            pos[x] = front--;
            add(tree, pos[x], 1);
        }
        return res;
    }
    private void add(int[] t, int i, int d) {
        for (; i < t.length; i += i & (-i)) t[i] += d;
    }
    private int sum(int[] t, int i) {
        int s = 0;
        for (; i > 0; i -= i & (-i)) s += t[i];
        return s;
    }
}

